// Shape of the UI data generated by scripts/build-data.ts from data/*.json.
import type { Bait, Fruit, Spot } from '../i18n/dictionaries.ts';

/** "HH:MM" or "MM-DD" window; `from > to` wraps over midnight / New Year. */
export type Window = { from: string; to: string };
/** `null` = unknown, `'always'` = any time / all year. */
export type Schedule = Window[] | 'always' | null;

/** Palm Island fishing zones (fishao.net zone grid, see palmZones.json). */
export const ZONES = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H'] as const;
export type Zone = typeof ZONES[number];
/**
 * Areas fished on the Palm Island map with its zones A–H: the island itself (zones from fishao.net)
 * and the Moray tournament (zones from fishao-tracker.cz). Their spots are "Zone A" … "Zone H".
 */
export const ZONED_AREAS = ['palm-island', 'moray-tournament'] as const;
export type ZonedArea = typeof ZONED_AREAS[number];
export const isZonedArea = (id: string): id is ZonedArea => (ZONED_AREAS as readonly string[]).includes(id);

/** How a fish becomes catchable (fishao.net), besides being in its area. */
export type Unlock =
  | { kind: 'set'; set: string }              // complete a furniture set (furnitureCollections id)
  | { kind: 'fossils'; name: string }         // complete the fossil collection "<name> fossils"
  | { kind: 'fruits'; fruits: Fruit[] }       // Jahni on Palm Island crushes these, in this order
  | { kind: 'clubPoints'; points: number }    // the club needs this many club points
  | { kind: 'clubEarly'; coins: number };     // unlocked early in club waters for fishcoins

export type Fish = {
  /** Stable progress key, never changes. */
  id: string;
  names: { cs: string; en: string };
  areas: string[];
  /**
   * Spots inside an area, e.g. { "pinheira-beach": ["Pier"] }. A spot is its own place: a fish
   * with a spot in an area bites only there, never in the open area (fishao.net).
   */
  spots: Record<string, Spot[]>;
  /**
   * Zones in its zoned area (all eight when the source lists none); `spots[area]` holds the same as "Zone X".
   * A fish is in at most one zoned area (checked by the build).
   */
  zones?: Zone[];
  time: Schedule;
  season: Schedule;
  rarity: 1 | 2 | 3 | 4 | 5;
  /** "n× rarer than other fish with the same stars" (fishao.net factor), only when > 1. */
  rarer?: number;
  bait: Bait[];
  /** Catch length range in cm (fishao.net), `null` = unknown. */
  size: { min: number; avg: number; max: number } | null;
  /** World record label ("449 cm", "(448–449 cm)?"), `null` = unknown. Already carries its own "?". */
  record: string | null;
  /**
   * Fish Market sell price ESTIMATE in fishbucks (fishao-tracker.cz calculation, not an official or
   * reported price): shown as "~min–max FB". Missing = unknown.
   */
  price?: { min: number; max: number };
  /** Breeding with Rex in the backyard: fishbucks, hours, success chance 0–1. Only Backyard fish. */
  breed?: { cost: number; hours: number; chance: number };
  unlock?: Unlock[];
  /** Every fish has a glowing variant (user decision, not from the source). */
  glowing: true;
  /** Natural size of public/fish/<id>.webp, for layout without shifts. */
  img: { w: number; h: number };
};

export type AreaKind = 'area' | 'tournament' | 'backyard';

export type Area = {
  id: string;
  name: string;
  kind: AreaKind;
  spots: Spot[];
  count: number;
  /** `false` = every fish bites only at a spot, so the area is just a heading over its spots. */
  open: boolean;
};

// ---- furniture (home decorations) ----------------------------------------

export type FurnitureType = 'wall' | 'floor' | 'furniture' | 'plant' | 'painting';
/** Most common first. `normal` (3 items) has no defined place in the source; it sits next to common. */
export const FURNITURE_RARITIES = ['very-common', 'common', 'normal', 'uncommon', 'rare', 'very-rare', 'epic', 'legendary'] as const;
export type FurnitureRarity = typeof FURNITURE_RARITIES[number];

/** How to get it: shop from a level, the Furniture Factory, a mission, free in the inventory, or closed-beta gift. */
export type Availability =
  | { kind: 'level'; level: number }
  | { kind: 'factory' } | { kind: 'mission' } | { kind: 'free' } | { kind: 'beta' };

/** Months 1–12, `from > to` wraps over New Year. */
export type MonthRange = { from: number; to: number };

export type FurnitureItem = {
  /** Stable progress key, never changes. */
  id: string;
  names: { cs: string; en: string };
  /** Set id, or 'plants' / 'paintings' / 'other' for items outside sets. */
  collection: string;
  type: FurnitureType | null;
  /** `null` = unknown. */
  rarity: FurnitureRarity | null;
  availability: Availability | null;
  /** In the shop only in these months; `null` = unknown. */
  season: MonthRange | 'always' | null;
  /** Shop price = home points the item adds (one number in every source); `null` = unknown. */
  price: number | null;
  /** Different prices from other sources: non-empty = disputed, the UI adds "?". */
  priceAlt: number[];
  img: { w: number; h: number };
};

export type FurnitureCollection = {
  id: string;
  /** set = a named furniture set; type = items outside sets grouped by type; other = the rest. */
  kind: 'set' | 'type' | 'other';
  names: { cs: string; en: string };
  /** public/furniture/sets/<id>.webp exists. */
  badge: boolean;
  count: number;
};
